import importlib.util
import pathlib
import unittest


SCRIPT = pathlib.Path(__file__).resolve().parents[1] / "color_parental_markers.py"
SPEC = importlib.util.spec_from_file_location("color_parental_markers", SCRIPT)
MODULE = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(MODULE)


class ParentalMarkerColorTests(unittest.TestCase):
    def test_low_marker_nodes_are_unassigned(self):
        self.assertEqual(MODULE.marker_color(99, 1, 0.9, 100), "#AAAAAA")

    def test_paternal_uses_blue_color(self):
        self.assertEqual(MODULE.marker_color(1, 101, 0.9, 100), "#8888FF")

    def test_maternal_uses_red_color(self):
        self.assertEqual(MODULE.marker_color(101, 1, 0.9, 100), "#FF8888")

    def test_mixed_marker_nodes_are_flagged(self):
        self.assertEqual(MODULE.marker_color(60, 50, 0.9, 100), "#FFFF00")

    def test_fraction_boundary_is_strict_like_legacy_rule(self):
        self.assertEqual(MODULE.marker_color(99, 11, 0.9, 100), "#FFFF00")


if __name__ == "__main__":
    unittest.main()
